$search=trim($_GET['q']??'');$like='%'.$search.'%';$s=$conn->prepare("SELECT * FROM visitors WHERE name LIKE ? OR pass_no LIKE ? OR phone LIKE ? ORDER BY created_at DESC");$s->bind_param('sss',$like,$like,$like);$s->execute();$result=$s->get_result();
